module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

    reg res_valid_reg;
    reg start_cnt;
    reg [3:0] cnt;
    reg [7:0] neg_divisor;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [17:0] SR;

    always@(posedge clk or posedge rst) begin
        if(rst==1'b1)begin
            res_valid_reg <= 1'b0;
            start_cnt <= 1'b0;
            cnt <= 4'b0;
            neg_divisor <= 8'b0;
            dividend_abs <= 8'b0;
            divisor_abs <= 8'b0;
            remainder <= 8'b0;
            quotient <= 8'b0;
            SR <= 18'b0;
        end else begin
            if(opn_valid==1'b1 && res_valid_reg==1'b0)begin
                dividend_abs <= (sign==1'b1)?((dividend[7]==1'b1)?(~dividend+1'b1):dividend):dividend;
                divisor_abs <= (sign==1'b1)?((divisor[7]==1'b1)?(~divisor+1'b1):divisor):divisor;
                SR <= {dividend_abs,1'b0};
                neg_divisor <= ~(divisor_abs)+1'b1;
                cnt <= 4'b1;
                start_cnt <= 1'b1;
            end else if(start_cnt==1'b1)begin
                if(cnt[3]==1'b1)begin
                    cnt <= 4'b0;
                    start_cnt <= 1'b0;
                    SR <= {remainder,quotient};
                end else begin
                    cnt <= cnt+1'b1;
                    case({SR[15],SR[14]})
                        2'b00:begin
                            remainder <= SR[15:8]+neg_divisor;
                            quotient <= SR[7:0];
                        end
                        2'b01:begin
                            remainder <= SR[15:8]+neg_divisor;
                            quotient <= SR[7:0];
                        end
                        2'b10:begin
                            remainder <= SR[15:8]+neg_divisor;
                            quotient <= SR[7:0];
                        end
                        2'b11:begin
                            remainder <= SR[15:8]+neg_divisor;
                            quotient <= SR[7:0];
                        end
                    endcase
                    SR <= {remainder[6:0],quotient[7],remainder[7]};
                end
            end
        end
    end
    assign res_valid=res_valid_reg;
    assign result={remainder,quotient};
endmodule
